def transform(grid):
    out = [row[:] for row in grid]
    # Correct the row patterns by completing the repeated motif.
    corrected = {
        1:  (1, 1, 1, 0, 1),
        3:  (1, 1, 1, 1, 1),
        5:  (1, 1, 1, 0, 1),
        7:  (1, 1, 1, 1, 1),
        9:  (0, 1, 1, 1, 1),
        11: (1, 1, 1, 1, 1),
    }
    starts = (0, 3, 6, 9, 12)
    for r, bits in corrected.items():
        if r >= len(out):
            continue
        for c, bit in zip(starts, bits):
            out[r][c] = grid[r][c]
            out[r][c + 1] = 0 if bit else grid[r][c]
    return out
